// Token usage by agent, model, and hour
// -------------------------------------------------------------------
// Purpose:  Raw token-monitoring view for the FinOps demo. Sums prompt
//           (input) and completion (output) tokens plus call count for
//           every agent/model, bucketed hourly.
// Source:   Application Insights `dependencies` table (GenAI OpenTelemetry
//           spans emitted by the demo agents / simulate_traffic.py).
// Notes:    Rows where gen_ai.agent.name / gen_ai.request.model are empty
//           are the auto-instrumented model-inference spans; their token
//           totals mirror the agent-attributed spans, so do NOT add both
//           populations or you double-count. Filter on isnotempty(agent)
//           when you want attributable usage only (see cost-by-agent-daily.kql).
// Run:      az monitor app-insights query --app <appName> -g <rg> \
//             --subscription <subId> --analytics-query "<this query>" -o table

dependencies
| where timestamp > ago(1d)
| extend inTok = toint(customDimensions["gen_ai.usage.input_tokens"]),
         outTok = toint(customDimensions["gen_ai.usage.output_tokens"]),
         model  = tostring(customDimensions["gen_ai.request.model"]),
         agent  = tostring(customDimensions["gen_ai.agent.name"])
| summarize prompt=sum(inTok), completion=sum(outTok), calls=count()
          by agent, model, bin(timestamp, 1h)
| order by timestamp asc

variables.$fxv#1:
// Token usage per agent (last 24h)
// -------------------------------------------------------------------
// Purpose:  Chargeback input showing which agent drives token volume.
// Source:   Application Insights `dependencies` table (GenAI spans).
// Filter:   isnotempty(gen_ai.agent.name) — keeps only attributable spans
//           and drops the untagged auto-instrumentation bucket.
// Pricing:  Join these measurements to the actual request/response model
//           and current customer-specific rates. Do not apply one rate to
//           every lab deployment or Model Router response.

dependencies
| where timestamp > ago(1d)
      and isnotempty(tostring(customDimensions["gen_ai.agent.name"]))
| extend inTok  = toint(customDimensions["gen_ai.usage.input_tokens"]),
         outTok = toint(customDimensions["gen_ai.usage.output_tokens"]),
         agent  = tostring(customDimensions["gen_ai.agent.name"])
| summarize prompt=sum(inTok), completion=sum(outTok), calls=count() by agent
| extend total_tokens=prompt+completion
| order by total_tokens desc

variables.$fxv#10:
// CHART — Tokens by agent (stacked column: prompt vs completion)
// -------------------------------------------------------------------
// Purpose:  Visual token-monitoring chart. Stacked column per agent
//           showing prompt (input) vs completion (output) tokens, so the
//           output-heavy agents stand out at a glance.
// Render:   Only draws in the Azure portal Logs / App Insights "Logs"
//           blade (or a Workbook). The `az ... query` CLI ignores render
//           and returns the table.
// Source:   Application Insights `dependencies` (GenAI spans); attributable
//           spans only (isnotempty(agent)).

dependencies
| where timestamp > ago(1d)
      and isnotempty(tostring(customDimensions["gen_ai.agent.name"]))
| extend inTok  = toint(customDimensions["gen_ai.usage.input_tokens"]),
         outTok = toint(customDimensions["gen_ai.usage.output_tokens"]),
         agent  = tostring(customDimensions["gen_ai.agent.name"])
| summarize prompt=sum(inTok), completion=sum(outTok) by agent
| order by completion desc
| render columnchart with (kind=stacked, title="Tokens by agent (prompt vs completion)", ytitle="tokens")

variables.$fxv#11:
// CHART — Token usage by agent (bar)
// -------------------------------------------------------------------
// Purpose:  Visual chargeback input. One bar per agent shows measured tokens.
// Render:   Portal Logs / Workbook only (CLI ignores render).
// Pricing:  Apply actual per-model rates outside this query.

dependencies
| where timestamp > ago(1d)
      and isnotempty(tostring(customDimensions["gen_ai.agent.name"]))
| extend inTok  = toint(customDimensions["gen_ai.usage.input_tokens"]),
         outTok = toint(customDimensions["gen_ai.usage.output_tokens"]),
         agent  = tostring(customDimensions["gen_ai.agent.name"])
| summarize total_tokens=sum(inTok)+sum(outTok) by agent
| order by total_tokens desc
| render barchart with (title="Measured tokens by agent", xtitle="tokens")

variables.$fxv#12:
// CHART — Token share by agent (pie)
// -------------------------------------------------------------------
// Purpose:  Visual usage chart. Each slice is an agent's share of tokens.
// Render:   Portal Logs / Workbook only (CLI ignores render).
// Pricing:  Token share is not cost share when model/token rates differ.

dependencies
| where timestamp > ago(1d)
      and isnotempty(tostring(customDimensions["gen_ai.agent.name"]))
| extend inTok  = toint(customDimensions["gen_ai.usage.input_tokens"]),
         outTok = toint(customDimensions["gen_ai.usage.output_tokens"]),
         agent  = tostring(customDimensions["gen_ai.agent.name"])
| summarize total_tokens=sum(inTok)+sum(outTok) by agent
| project agent, total_tokens
| render piechart with (title="Token share by agent")

variables.$fxv#13:
// CHART — Completion-token trend per agent (timechart)
// -------------------------------------------------------------------
// Purpose:  Visual trend chart. Completion tokens per hour, one line per
//           agent, to spot bursts, steady load, or idle periods.
// Render:   Portal Logs / Workbook only (CLI ignores render). timechart
//           pivots the `agent` string column into one series per agent.
// Source:   Application Insights `dependencies` (GenAI spans); attributable
//           spans only. Widen ago(1d) / change bin() as needed.

dependencies
| where timestamp > ago(1d)
      and isnotempty(tostring(customDimensions["gen_ai.agent.name"]))
| extend outTok = toint(customDimensions["gen_ai.usage.output_tokens"]),
         agent  = tostring(customDimensions["gen_ai.agent.name"])
| summarize completion=sum(outTok) by bin(timestamp, 1h), agent
| render timechart with (title="Completion tokens per hour by agent", ytitle="completion tokens")

